const root = new URL('../', import.meta.url);
const sw = await readFile(new URL('sw.js', root), 'utf8');
const shell = [...(/const SHELL = \[([\s\S]*?)\];/.exec(sw)?.[1] ?? '').matchAll(/'(\/[^']+\.(?:js|css))'/g)].map((m) => m[1]);
let total = 0;
for (const p of shell) total += (await stat(new URL(p.slice(1), root))).size;
total += (await stat(new URL('sw.js', root))).size;
console.log(`shipped JS + CSS: ${(total / 1024).toFixed(1)} KiB (budget ${BUDGET / 1024} KiB)`);
if (total > BUDGET) {
  console.error('Over budget: trim code or raise the budget on purpose.');
  process.exit(1);
}
// A language's words (l10n/<tag>.json) are not in the shell: one language is fetched once a version. Each has a budget of its own,
// so a catalog can't grow unseen (localization design, section 3).
const CATALOG = 200 * 1024;
for (const f of (await readdir(new URL('l10n/', root)).catch(() => /** @type {string[]} */ ([]))).filter((n) => n.endsWith('.json') && n !== 'languages.json')) {
  const size = (await stat(new URL(`l10n/${f}`, root))).size;
  console.log(`l10n/${f}: ${(size / 1024).toFixed(1)} KiB (budget ${CATALOG / 1024} KiB)`);
  if (size > CATALOG) {
    console.error(`${f} is over its budget: shorten the words or raise the budget on purpose.`);
    process.exit(1);
  }
}
